import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { TransactionSchema } from "../src/domain/transaction.js";
import { FeatureExtractor } from "../src/features/extractor.js";
import { loadGeoTable } from "../src/features/geo.js";
import { InMemoryFeatureStore } from "../src/features/store.js";
import { FEATURE_NAMES, type Features } from "../src/features/types.js";

// Generated by the Python implementation: uv run python -m vigil_ml.golden
const golden = JSON.parse(
  readFileSync(new URL("../../contracts/golden/features.json", import.meta.url), "utf8"),
) as { spec_version: number; streams: { name: string; transactions: unknown[]; features: Features[] }[] };

const TOLERANCE = 1e-6;

describe("feature parity with Python (contracts/golden/features.json)", () => {
  it("is spec version 1", () => {
    expect(golden.spec_version).toBe(1);
  });

  for (const stream of golden.streams) {
    it(`matches every feature on the "${stream.name}" stream`, async () => {
      const extractor = new FeatureExtractor(new InMemoryFeatureStore(), loadGeoTable());
      const mismatches: string[] = [];

      for (const [i, raw] of stream.transactions.entries()) {
        const txn = TransactionSchema.parse(raw); // golden inputs must be valid API payloads
        const actual = await extractor.extract(txn);
        await extractor.record(txn);
        const expected = stream.features[i]!;

        expect(Object.keys(actual)).toEqual([...FEATURE_NAMES]);
        for (const name of FEATURE_NAMES) {
          const [a, e] = [actual[name], expected[name]];
          const equal = a === null || e === null ? a === e : Math.abs(a - e) <= TOLERANCE;
          if (!equal) mismatches.push(`${txn.transaction_id}.${name}: ts=${a} py=${e}`);
        }
      }
      expect(mismatches).toEqual([]);
    });
  }
});
